using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace FactoryArena.Editor {
public static class FactoryBuilder {
 static Material steel,floor,yellow,dark,red,cyan; static Transform root;
 static Material Mat(string n,Color c,float metal=0){var path="Assets/FactoryArena/Materials/"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.color=c;m.SetFloat("_Metallic",metal);m.SetFloat("_Smoothness",.35f);return m;}
 static GameObject Part(string n,Transform parent,Vector3 p,Vector3 s,Material m,PrimitiveType type=PrimitiveType.Cube,bool solid=true){var g=GameObject.CreatePrimitive(type);g.name=n;g.transform.SetParent(parent,false);g.transform.localPosition=p;g.transform.localScale=s;g.GetComponent<Renderer>().sharedMaterial=m;if(!solid)Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static Transform Group(string n,Transform p){var g=new GameObject(n);g.transform.SetParent(p,false);return g.transform;}
 static Light Lamp(Transform p,Vector3 pos,Color c){var g=new GameObject("Industrial light");g.transform.SetParent(p,false);g.transform.localPosition=pos;var l=g.AddComponent<Light>();l.type=LightType.Point;l.color=c;l.range=8;l.intensity=3;return l;}
 static void Save(Transform t,string name){PrefabUtility.SaveAsPrefabAssetAndConnect(t.gameObject,"Assets/FactoryArena/Prefabs/"+name+".prefab",InteractionMode.AutomatedAction);}
 [MenuItem("Tools/Factory Arena/Build")]
 public static void Build(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);root=Group("FactoryArena",null);steel=Mat("Steel",new Color(.32f,.43f,.52f),.6f);floor=Mat("Deck",new Color(.12f,.22f,.29f),.3f);yellow=Mat("Safety yellow",new Color(1,.65f,.08f),.2f);dark=Mat("Graphite",new Color(.035f,.065f,.10f));red=Mat("Warning orange",new Color(1,.15f,.04f));cyan=Mat("Signal cyan",new Color(.1f,.85f,1));
 var env=Group("Environment",root);var platform=Group("MainPlatform",env);Part("Structural deck",platform,new Vector3(0,-.5f,0),new Vector3(28,1,20),floor);
 for(int x=-12;x<=12;x+=4)for(int z=-8;z<=8;z+=4){Part("Deck seam",platform,new Vector3(x,.008f,z),new Vector3(3.92f,.02f,3.92f),steel);Part("Deck inset",platform,new Vector3(x,.024f,z),new Vector3(3.82f,.02f,3.82f),floor);}
 for(int i=-12;i<=12;i+=3){Part("Underside crossbeam",platform,new Vector3(i,-1.2f,0),new Vector3(.35f,1,20),dark);foreach(int z in new[]{-10,10}){Part("Edge warning",platform,new Vector3(i,.04f,z),new Vector3(1.4f,.06f,.22f),yellow);}}
 foreach(int x in new[]{-13,13})foreach(int z in new[]{-7,7}){Part("Tower leg",platform,new Vector3(x,-5,z),new Vector3(.8f,9,.8f),steel);Part("Foot",platform,new Vector3(x,-9,z),new Vector3(2,.5f,2),yellow);}
 Save(platform,"FactoryPlatform");var rails=Group("PartialRailings",env);foreach(int z in new[]{-10,10})foreach(int x in new[]{-10,10}){for(int j=-1;j<=1;j++)Part("Guard post",rails,new Vector3(x+j*1.5f,.65f,z),new Vector3(.12f,1.3f,.12f),yellow);Part("Guard rail",rails,new Vector3(x,1.2f,z),new Vector3(3.3f,.12f,.12f),steel);}
 var machine=Group("Machinery",root);var belts=new ConveyorBelt[2];for(int k=0;k<2;k++){var b=Group(k==0?"Conveyor_A":"Conveyor_B",machine);b.localPosition=new Vector3(0,.2f,k==0?5:-5);var surface=Part("Moving belt",b,Vector3.zero,new Vector3(20,.4f,2.8f),dark);belts[k]=surface.AddComponent<ConveyorBelt>();belts[k].direction=k==0?1:-1;for(int j=-9;j<=9;j++){Part("Belt tread",b,new Vector3(j,.215f,0),new Vector3(.12f,.03f,2.65f),steel,PrimitiveType.Cube,false);}foreach(int z in new[]{-1,1})Part("Side housing",b,new Vector3(0,-.1f,z*1.6f),new Vector3(21,.6f,.22f),yellow);foreach(int x in new[]{-10,10}){var roll=Part("End roller",b,new Vector3(x,0,0),new Vector3(.7f,1.45f,.7f),steel,PrimitiveType.Cylinder);roll.transform.localRotation=Quaternion.Euler(90,0,0);Part("Motor",b,new Vector3(x,-.05f,2),new Vector3(1,.7f,.7f),cyan); }Save(b,k==0?"ConveyorBelt":"ConveyorBeltReverse");}
 var press=Group("HydraulicPress",machine);foreach(int x in new[]{-3,3})foreach(int z in new[]{-2,2}){Part("Column foot",press,new Vector3(x,.2f,z),new Vector3(1,.4f,1),dark);Part("Hydraulic column",press,new Vector3(x,2.8f,z),new Vector3(.6f,5.6f,.6f),yellow);Part("Chrome guide",press,new Vector3(x*.82f,2.8f,z),new Vector3(.2f,5,.2f),steel,PrimitiveType.Cylinder);}
 Part("Crown",press,new Vector3(0,5.5f,0),new Vector3(7,1,5),yellow);Part("Hydraulic ram",press,new Vector3(0,4.8f,0),new Vector3(.9f,.9f,.9f),steel,PrimitiveType.Cylinder);var plate=Part("Press plate",press,new Vector3(0,4,0),new Vector3(4.5f,.6f,3),steel);var rb=plate.AddComponent<Rigidbody>();rb.isKinematic=true;rb.interpolation=RigidbodyInterpolation.Interpolate;Part("Anvil",press,new Vector3(0,.12f,0),new Vector3(4.5f,.24f,3),dark);for(int i=-4;i<=4;i++){Part("Hazard stripe",press,new Vector3(i*.65f,.06f,2.8f),new Vector3(.32f,.08f,.65f),i%2==0?yellow:dark,PrimitiveType.Cube,false);}
 var h=Group("PressHazard",press);h.localPosition=new Vector3(0,.6f,0);var hc=h.gameObject.AddComponent<BoxCollider>();hc.size=new Vector3(4.3f,1,2.8f);hc.isTrigger=true;var hz=h.gameObject.AddComponent<HazardZone>();var pr=press.gameObject.AddComponent<HydraulicPress>();pr.plate=rb;pr.hazard=hz;pr.beacon=Lamp(press,new Vector3(0,3,0),Color.red);Save(press,"HydraulicPress");
 var interact=Group("Interactables",root);for(int k=0;k<2;k++){var l=Group(k==0?"Lever_A":"Lever_B",interact);l.localPosition=new Vector3(k==0?-10:10,0,0);Part("Access plinth",l,new Vector3(0,.1f,0),new Vector3(2,.2f,2),steel);Part("Console",l,new Vector3(0,.65f,0),new Vector3(1,1,1),yellow);var pivot=Group("Lever pivot",l);pivot.localPosition=new Vector3(0,1.2f,0);Part("Shaft",pivot,new Vector3(0,.4f,0),new Vector3(.15f,.8f,.15f),steel);Part("Red grip",pivot,new Vector3(0,.85f,0),new Vector3(.45f,.3f,.3f),red,PrimitiveType.Capsule);var lever=l.gameObject.AddComponent<ControlLever>();lever.handle=pivot;lever.indicator=Lamp(l,new Vector3(0,1.3f,.5f),Color.green);Save(l,"ControlLever"+(k==0?"A":"B"));lever.belt=belts[k];PrefabUtility.RecordPrefabInstancePropertyModifications(lever);}
 var hazards=Group("Hazards",root);var fall=Group("FallDetection",hazards);fall.localPosition=new Vector3(0,-6,0);var fc=fall.gameObject.AddComponent<BoxCollider>();fc.size=new Vector3(80,1,70);fc.isTrigger=true;fall.gameObject.AddComponent<HazardZone>();
 var sp=Group("SpawnPoints",root);int index=0;foreach(int z in new[]{-8,8})foreach(int x in new[]{-8,8}){var s=Group("SpawnPoint_"+(++index).ToString("00"),sp);s.localPosition=new Vector3(x,1.1f,z);s.LookAt(new Vector3(0,1.1f,0));Part("Spawn marker",sp,new Vector3(x,.055f,z),new Vector3(1.4f,.03f,1.4f),cyan,PrimitiveType.Cylinder,false);}
 var bg=Group("BackgroundDecoration",env);for(int i=-2;i<=2;i++){var pipe=Part("Lower pipe",bg,new Vector3(i*6,-5,-2),new Vector3(1.2f,17,1.2f),steel,PrimitiveType.Cylinder,false);pipe.transform.localRotation=Quaternion.Euler(90,0,0);Part("Distant tower",bg,new Vector3(i*10,-5,19),new Vector3(3,14,3),dark,PrimitiveType.Cube,false);Part("Tower cap",bg,new Vector3(i*10,2,19),new Vector3(4,.5f,4),yellow,PrimitiveType.Cube,false);}
 var light=Group("Lighting",root);var sun=Group("Key light",light).gameObject.AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=2;sun.shadows=LightShadows.Soft;sun.transform.rotation=Quaternion.Euler(45,-35,0);RenderSettings.ambientLight=new Color(.4f,.5f,.65f);Lamp(light,new Vector3(-8,6,0),new Color(.4f,.7f,1));Lamp(light,new Vector3(8,6,0),new Color(1,.6f,.3f));var camera=Group("PreviewCamera",root).gameObject.AddComponent<Camera>();camera.tag="MainCamera";camera.transform.position=new Vector3(28,30,-35);camera.transform.LookAt(new Vector3(0,0,0));camera.fieldOfView=48;camera.backgroundColor=new Color(.035f,.06f,.1f);camera.clearFlags=CameraClearFlags.SolidColor;camera.gameObject.AddComponent<AudioListener>();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/FactoryArena/Scenes/FactoryArena.unity");AssetDatabase.SaveAssets();}
}
}

